package main

import "sync"

func main() {
	var counter int
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			counter++ // DATA RACE: unsynchronized read-modify-write on shared memory
		}()
	}
	wg.Wait()
	// `go run -race` flags this. A logical race condition (e.g. deposit-then-withdraw
	// ordering under a correct lock) would NOT be flagged — the detector finds data races only.
	_ = counter
}

// The race detector is a build/run flag, not code. Typical invocations:
//
//   go test -race ./...          // instrument & run all package tests
//   go run -race main.go         // run a program under the detector
//   go build -race -o app ./cmd  // produce an instrumented binary
//
// Exit status 66 signals that at least one data race was found.
// $ go test -race ./...
// ==================
// WARNING: DATA RACE
// ...
// FAIL  example/pkg  0.312s   (exit status 66)

package main

import (
	"fmt"
	"sync"
)

func main() {
	var x int
	ch := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		x = 42     // TSan stamps this write with goroutine 2's vector clock
		ch <- struct{}{} // channel send ADVANCES clocks -> happens-before edge
	}()
	<-ch          // receive: merges the sender's clock; now our access is ORDERED after x=42
	fmt.Println(x) // no race: the two accesses are ordered, so TSan stays silent
	wg.Wait()
	// Output: 42
}

package main

import (
	"sync"
	"testing"
)

// A stress test forces many interleavings so a latent race actually surfaces
// under -race. Run: go test -race -run TestStress -count=10
func TestStress(t *testing.T) {
	m := map[int]int{}
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func(k int) {
			defer wg.Done()
			m[k] = k // concurrent map write -> detector reports it ONLY if this path runs
		}(i)
	}
	wg.Wait()
}

// A representative report printed by `go run -race`:
//
// ==================
// WARNING: DATA RACE
// Read at 0x00c0000160a0 by goroutine 8:
//   main.main.func1()
//       /app/main.go:16 +0x3c
//
// Previous write at 0x00c0000160a0 by goroutine 7:
//   main.main.func1()
//       /app/main.go:16 +0x50
//
// Goroutine 8 (running) created at:
//   main.main()  /app/main.go:13 +0xd4
// ==================
//
// Read top-down: conflicting access, previous access, then each goroutine's
// creation site. 0x...16a0 is the shared variable to guard.

// GORACE is a space-separated options string read by the TSan runtime at start.
//
//   # stop at the first race found (fail fast in CI):
//   GORACE='halt_on_error=1' go test -race ./...
//
//   # deepen per-goroutine access history to trace older accesses:
//   GORACE='history_size=4' go test -race ./...
//
//   # write reports to files race.<pid> instead of stderr:
//   GORACE='log_path=/tmp/race' go test -race ./...
//
// Because of the ~5-10x CPU/memory cost, these run in tests/CI, not production.

