package solution

import "sync"

// Counter is safe for concurrent use: a mutex orders every access to n,
// establishing happens-before edges the race detector requires.
type Counter struct {
	mu sync.Mutex
	n  int64
}

func (c *Counter) Inc() {
	c.mu.Lock()
	c.n++ // read-modify-write protected by the lock
	c.mu.Unlock()
}

func (c *Counter) Value() int64 {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

