package solution

import (
	"sync"
	"testing"
)

// Run with: go test -race
func TestCounterConcurrent(t *testing.T) {
	cases := []struct {
		goroutines int
		perG       int
		want       int64
	}{
		{10, 100, 1000},
		{50, 20, 1000},
		{1, 500, 500},
	}
	for _, c := range cases {
		var counter Counter
		var wg sync.WaitGroup
		for i := 0; i < c.goroutines; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for j := 0; j < c.perG; j++ {
					counter.Inc()
				}
			}()
		}
		wg.Wait()
		if got := counter.Value(); got != c.want {
			t.Errorf("goroutines=%d perG=%d: got %d want %d", c.goroutines, c.perG, got, c.want)
		}
	}
}

