func CountWords(docs []string) map[string]int {
	counts := make(map[string]int)
	var mu sync.Mutex // orders all map writes
	var wg sync.WaitGroup
	for _, doc := range docs {
		wg.Add(1)
		go func(d string) {
			defer wg.Done()
			mu.Lock()
			counts[d]++ // now a single goroutine touches the map at a time
			mu.Unlock()
		}(doc)
	}
	wg.Wait()
	return counts
}

package solution

import "sync"

// SafeMap is safe for concurrent use: the RWMutex orders every access
// to m, giving the happens-before relationships the race detector needs.
type SafeMap struct {
	mu sync.RWMutex
	m  map[string]int
}

func NewSafeMap() *SafeMap {
	return &SafeMap{m: make(map[string]int)}
}

// Inc increments the count for key by one (writer).
func (s *SafeMap) Inc(key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.m[key]++
}

// Get returns the current count for key (reader).
func (s *SafeMap) Get(key string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.m[key]
}

package solution

import "sync"

// ProcessAll squares each item concurrently; race-free and correct.
func ProcessAll(items []int) []int {
	out := make([]int, len(items))
	var wg sync.WaitGroup
	for i, v := range items {
		wg.Add(1)
		// Pass i and v as arguments so each goroutine gets its own copy
		// (avoids the shared loop-variable data race pre-Go 1.22).
		go func(idx, val int) {
			defer wg.Done()
			out[idx] = val * val // distinct index per goroutine: no shared-slot race
		}(i, v)
	}
	wg.Wait() // Wait happens-after every Done -> all writes visible before return
	return out
}

